<?php

namespace App\Services;

use JsonException;

/**
 * Compact copy of Bounce Back Realty's original document content.
 *
 * The repeated inline logo is replaced with a tenant-aware image URL when a
 * document is merged, keeping the source compact without changing the clauses
 * or layout of the original forms.
 */
final class OriginalDocumentTemplateLibrary
{
    private const COMPRESSED_TEMPLATES = '';

    /**
     * @return array<int, array{name:string,type:string,content:string,merge_fields:array<int,string>,input_fields:array<int,array<string,mixed>>,is_default:bool}>
     *
     * @throws JsonException
     */
    public static function templates(): array
    {
        $compressed = base64_decode(self::COMPRESSED_TEMPLATES, true);
        $json = $compressed === false ? false : gzdecode($compressed);

        if ($json === false) {
            throw new \RuntimeException('The original document template library could not be decoded.');
        }

        /** @var array<int, array{name:string,type:string,content:string,merge_fields:array<int,string>,input_fields:array<int,array<string,mixed>>,is_default:bool}> $templates */
        $templates = json_decode($json, true, 512, JSON_THROW_ON_ERROR);

        return array_map(static function (array $template): array {
            $template['merge_fields'] = array_values(array_unique([
                ...($template['merge_fields'] ?? []),
                'company.document_logo_url',
            ]));

            return $template;
        }, $templates);
    }
}
